-- ------------------------------------------------------------------
-- Medicine database (MedEx sample) - MySQL 8.0.33
-- Source: sample_med_csv.zip (6 CSV files)
-- Engine InnoDB, charset utf8mb4 (needed for the Taka sign U+09F3)
-- ------------------------------------------------------------------
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET UNIQUE_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';

CREATE DATABASE IF NOT EXISTS medicine_db
  DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE medicine_db;

DROP TABLE IF EXISTS medicines;
DROP TABLE IF EXISTS generic_indications;
DROP TABLE IF EXISTS generics;
DROP TABLE IF EXISTS manufacturers;
DROP TABLE IF EXISTS dosage_forms;
DROP TABLE IF EXISTS indications;
DROP TABLE IF EXISTS drug_classes;

CREATE TABLE drug_classes (
  drug_class_id   INT UNSIGNED NOT NULL,
  name            VARCHAR(100) NOT NULL,
  slug            VARCHAR(120) NOT NULL,
  generics_count  INT UNSIGNED NULL,
  PRIMARY KEY (drug_class_id),
  UNIQUE KEY uq_drug_classes_slug (slug),
  KEY idx_drug_classes_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE indications (
  indication_id   INT UNSIGNED NOT NULL,
  name            VARCHAR(150) NOT NULL,
  slug            VARCHAR(160) NOT NULL,
  generics_count  INT UNSIGNED NULL,
  PRIMARY KEY (indication_id),
  UNIQUE KEY uq_indications_name (name),
  UNIQUE KEY uq_indications_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE dosage_forms (
  dosage_form_id    INT UNSIGNED NOT NULL,
  name              VARCHAR(60) NOT NULL,
  slug              VARCHAR(70) NOT NULL,
  brand_names_count INT UNSIGNED NULL,
  PRIMARY KEY (dosage_form_id),
  UNIQUE KEY uq_dosage_forms_name (name),
  UNIQUE KEY uq_dosage_forms_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE manufacturers (
  manufacturer_id   INT UNSIGNED NOT NULL,
  name              VARCHAR(100) NOT NULL,
  slug              VARCHAR(120) NOT NULL,
  generics_count    INT UNSIGNED NULL,
  brand_names_count INT UNSIGNED NULL,
  PRIMARY KEY (manufacturer_id),
  UNIQUE KEY uq_manufacturers_name (name),
  UNIQUE KEY uq_manufacturers_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE generics (
  generic_id                          INT UNSIGNED NOT NULL,
  name                                VARCHAR(150) NOT NULL,
  slug                                VARCHAR(150) NOT NULL,
  monograph_link                      VARCHAR(500) NULL,
  drug_class_id                       INT UNSIGNED NULL,
  indication_id                       INT UNSIGNED NULL,
  indication_description              MEDIUMTEXT NULL,
  therapeutic_class_description       TEXT NULL,
  pharmacology_description            MEDIUMTEXT NULL,
  dosage_description                  MEDIUMTEXT NULL,
  administration_description          MEDIUMTEXT NULL,
  interaction_description             MEDIUMTEXT NULL,
  contraindications_description       MEDIUMTEXT NULL,
  side_effects_description            MEDIUMTEXT NULL,
  pregnancy_lactation_description     MEDIUMTEXT NULL,
  precautions_description             MEDIUMTEXT NULL,
  pediatric_usage_description         MEDIUMTEXT NULL,
  overdose_effects_description        MEDIUMTEXT NULL,
  duration_of_treatment_description   TEXT NULL,
  reconstitution_description          TEXT NULL,
  storage_conditions_description      TEXT NULL,
  descriptions_count                  TINYINT UNSIGNED NULL,
  PRIMARY KEY (generic_id),
  UNIQUE KEY uq_generics_name (name),
  UNIQUE KEY uq_generics_slug (slug),
  KEY idx_generics_drug_class (drug_class_id),
  KEY idx_generics_indication (indication_id),
  CONSTRAINT fk_generics_drug_class FOREIGN KEY (drug_class_id)
    REFERENCES drug_classes (drug_class_id) ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_generics_indication FOREIGN KEY (indication_id)
    REFERENCES indications (indication_id) ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE medicines (
  brand_id          INT UNSIGNED NOT NULL,
  brand_name        VARCHAR(100) NOT NULL,
  type              ENUM('allopathic','herbal') NOT NULL,
  slug              VARCHAR(120) NOT NULL,
  dosage_form_id    INT UNSIGNED NOT NULL,
  generic_id        INT UNSIGNED NULL,
  strength          VARCHAR(100) NULL,
  manufacturer_id   INT UNSIGNED NOT NULL,
  package_container VARCHAR(500) NULL,
  package_size      VARCHAR(200) NULL,
  PRIMARY KEY (brand_id),
  KEY idx_medicines_slug (slug),
  KEY idx_medicines_brand_name (brand_name),
  KEY idx_medicines_dosage_form (dosage_form_id),
  KEY idx_medicines_generic (generic_id),
  KEY idx_medicines_manufacturer (manufacturer_id),
  CONSTRAINT fk_medicines_dosage_form FOREIGN KEY (dosage_form_id)
    REFERENCES dosage_forms (dosage_form_id) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_medicines_generic FOREIGN KEY (generic_id)
    REFERENCES generics (generic_id) ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_medicines_manufacturer FOREIGN KEY (manufacturer_id)
    REFERENCES manufacturers (manufacturer_id) ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

